#[cfg(test)]
mod invariants {
    use super::*;
    #[test]
    fn dictionary_keys_are_sorted_and_unique() {
        macro_rules! sorted { ($($table:ident),+ $(,)?) => {$(
            for pair in $table.windows(2) {
                assert!(pair[0].0 < pair[1].0, "unsorted/duplicate key in {}: {:?}", stringify!($table), pair[0].0);
            }
        )+}; }
        sorted!(
            CONSONANTS,
            VOWELS,
            KANA,
            DIPHTHONGS,
            MINOR_DIPHTHONGS,
            EXCEPTION_KANA,
            PARTICLE_EXCEPTIONS,
            USERS_MAP,
            ABSTRACT_MAP,
            ABSTRACT_MAP_LEFT,
            ABSTRACT_MAP_RIGHT,
            CONJUGATE_GODAN_MAP,
            CONJUGATE_KAMI_MAP,
            CONJUGATE_SIMO_MAP,
            DESU,
            ROMAJI,
            JIS
        );
        assert_eq!(AUXILIARIES.len(), 64);
        for (_, row) in KANA {
            assert_eq!(row.len(), 8);
        }
        for &(index, _) in AUXILIARIES {
            assert!(index < 10);
        }
    }
}
